  // Function for MATLAB Function: '<S31>/optimizer'
  double AccController::ACC_Controller_norm(const double x[13])
  {
    double scale;
    double y;
    int32_t k;
    y = 0.0;
    scale = 3.312168642111238E-170;
    for (k = 0; k < 13; k++) {
      double absxk;
      absxk = std::abs(x[k]);
      if (absxk > scale) {
        double t;
        t = scale / absxk;
        y = y * t * t + 1.0;
        scale = absxk;
      } else {
        double t;
        t = absxk / scale;
        y += t * t;
      }
    }

    y = scale * std::sqrt(y);
    if (std::isnan(y)) {
      k = 0;
      int32_t exitg1;
      do {
        exitg1 = 0;
        if (k < 13) {
          if (std::isnan(x[k])) {
            exitg1 = 1;
          } else {
            k++;
          }
        } else {
          y = (rtInf);
          exitg1 = 1;
        }
      } while (exitg1 == 0);
    }

    return y;
  }

  // Function for MATLAB Function: '<S53>/optimizer'
  double AccController::ACC_Controller_toc_h(double tstart_tv_sec, double
    tstart_tv_nsec)
  {
    coderTimespec origTimespec;
    if (!ACC_Controller_DW.freq_not_empty) {
      ACC_Controller_DW.freq_not_empty = true;
      coderInitTimeFunctions(&ACC_Controller_DW.freq);
    }

    coderTimeClockGettimeMonotonic(&origTimespec, ACC_Controller_DW.freq);
    return (origTimespec.tv_nsec - tstart_tv_nsec) / 1.0E+9 +
      (origTimespec.tv_sec - tstart_tv_sec);
  }

